import { createHash } from 'node:crypto';

/**
 * The registry is the contract between the customer's Next.js app and the
 * Web Agent (docs/initiatives/nextjs_web_agents, PLAN §3): a list of
 * operations with a stable name and a lazy import of the real function.
 * Generated by `faustine-next init`, committed, reviewed in PRs. Names are
 * Faustine's (`module.action`, the vocabulary of the generated SDK); the
 * bindings are the app's. No business logic lives here.
 */

/** The current shape of a registry; bumped when the handler contract changes. */
export const REGISTRY_FORMAT_VERSION = 1;

export type OperationName = `${string}.${string}`;

/** A function the agent may call: a Server Action or a server-only function, any parameter list (see `params`). */
export type OperationFn = (...args: never[]) => unknown;

export type OperationParamKind = 'value' | 'formData' | 'prevState';
/**
 * One parameter of the bound function, in order: a name (a plain value), or
 * `{ name, kind }` for a `FormData` parameter (built from the input's fields)
 * and the previous state of a `useActionState` action (never sent). How the
 * handler turns the agent's input into the call:
 * - no `params`, or exactly one value parameter: `fn(input)` — the body IS the argument;
 * - one `FormData` parameter: `fn(toFormData(input))`;
 * - several: the body is an object keyed by parameter names, `fn(input.a, input.b, …)`.
 */
export type OperationParam = string | { name: string; kind?: OperationParamKind };

/**
 * An input validator: zod-like (`safeParse`) or a plain function that throws.
 * Loaded lazily like the function so the schema module stays out of the bundle
 * until the operation runs.
 */
export type OperationSchema =
  | { safeParse: (input: unknown) => { success: true; data: unknown } | { success: false; error: unknown } }
  | { parse: (input: unknown) => unknown }
  | ((input: unknown) => unknown);

export interface OperationBinding {
  /** Loads the function on first use: `() => import('@/app/deals/actions').then(m => m.createDeal)`. */
  fn: () => Promise<OperationFn> | OperationFn;
  /** Optional input schema, loaded the same way. */
  schema?: () => Promise<OperationSchema> | OperationSchema;
  /** A hint for the chat: ask the user before running this (the portal can override it). */
  confirm?: boolean;
  /** The function's parameters, written by the generator from its signature (see `OperationParam`). */
  params?: OperationParam[];
}

export function normalizeParams(params: OperationParam[] | undefined): { name: string; kind: OperationParamKind }[] | null {
  if (!params) return null;
  return params.map((p) => (typeof p === 'string' ? { name: p, kind: 'value' as const } : { name: p.name, kind: p.kind ?? 'value' }));
}

export interface RegistryMeta {
  /** The Web Agent this registry binds (`wa_…` or the assistant id). */
  webAgent: string;
  formatVersion?: number;
}

export interface Registry {
  readonly webAgent: string;
  readonly formatVersion: number;
  /** Operation names in a stable order. */
  readonly operations: readonly OperationName[];
  /** Content hash over the names, their schema presence and the format version. */
  readonly hash: string;
  readonly bindings: Readonly<Record<OperationName, OperationBinding>>;
}

const NAME_RE = /^[a-z][A-Za-z0-9]*\.[a-z][A-Za-z0-9]*$/;

export function isOperationName(name: string): name is OperationName {
  return NAME_RE.test(name);
}

/** The deterministic hash of a registry: what `init` reports, what the handler answers, what the portal compares. */
export interface HashEntry {
  name: string;
  schema: boolean;
  confirm: boolean;
  /** The normalized parameter list, when the line carries one: part of the contract the deployed app honours. */
  params?: { name: string; kind: OperationParamKind }[] | null;
}

export function registryHash(meta: { webAgent: string; formatVersion: number }, entries: HashEntry[]): string {
  const canonical = JSON.stringify({
    webAgent: meta.webAgent,
    formatVersion: meta.formatVersion,
    operations: [...entries]
      .sort((a, b) => a.name.localeCompare(b.name))
      .map((e) => (e.params ? { name: e.name, schema: e.schema, confirm: e.confirm, params: e.params } : { name: e.name, schema: e.schema, confirm: e.confirm })),
  });
  return createHash('sha256').update(canonical).digest('hex').slice(0, 16);
}

/**
 * Builds the registry. Validates every name once at module load, so a typo
 * fails the build of the customer's app, not a request.
 */
export function createRegistry(meta: RegistryMeta, map: Record<string, OperationBinding>): Registry {
  if (!meta || typeof meta.webAgent !== 'string' || !meta.webAgent.trim()) {
    throw new Error('createRegistry: `webAgent` is required — the Web Agent id this registry binds.');
  }
  const formatVersion = meta.formatVersion ?? REGISTRY_FORMAT_VERSION;
  if (formatVersion !== REGISTRY_FORMAT_VERSION) {
    throw new Error(
      `createRegistry: formatVersion ${formatVersion} is not supported by this version of @faustine-ai/next (expects ${REGISTRY_FORMAT_VERSION}). Run \`npx faustine-next init\` again.`,
    );
  }
  const names = Object.keys(map).sort();
  const bindings: Record<string, OperationBinding> = {};
  for (const name of names) {
    if (!isOperationName(name)) {
      throw new Error(
        `createRegistry: "${name}" is not a valid operation name — expected "module.action" in camelCase (e.g. "deals.create").`,
      );
    }
    const binding = map[name];
    if (!binding || typeof binding.fn !== 'function') {
      throw new Error(`createRegistry: "${name}" needs a \`fn\` that imports the server function.`);
    }
    if (binding.params !== undefined) {
      const ok = Array.isArray(binding.params) && binding.params.every((p) => typeof p === 'string' || (p && typeof p.name === 'string'));
      if (!ok) throw new Error(`createRegistry: "${name}" has a malformed \`params\` — a list of parameter names or { name, kind }.`);
    }
    bindings[name] = binding;
  }
  const hash = registryHash(
    { webAgent: meta.webAgent, formatVersion },
    names.map((name) => ({ name, schema: Boolean(map[name].schema), confirm: Boolean(map[name].confirm), params: normalizeParams(map[name].params) })),
  );
  return Object.freeze({
    webAgent: meta.webAgent,
    formatVersion,
    operations: Object.freeze(names as OperationName[]),
    hash,
    bindings: Object.freeze(bindings) as Readonly<Record<OperationName, OperationBinding>>,
  });
}
